// Rust guideline compliant 2026-02-21
use gpui_mesh::{DataSet, Field};
use gpui_profiler::AllocProbe;
use gpui_scene3d::{Actor, GpuChunk, prepare_chunks};
use std::{hint::black_box, time::Instant};
fn cpu_ns() -> u128 {
    let mut stamp = libc::timespec {
        tv_sec: 0,
        tv_nsec: 0,
    };
    // SAFETY: stamp is valid writable storage for this synchronous clock call,
    // which retains no pointer. Its status and returned timestamp are checked.
    let result = unsafe { libc::clock_gettime(libc::CLOCK_PROCESS_CPUTIME_ID, &mut stamp) };
    assert_eq!(result, 0);
    assert!(stamp.tv_sec >= 0 && (0..1_000_000_000).contains(&stamp.tv_nsec));
    stamp.tv_sec as u128 * 1_000_000_000 + stamp.tv_nsec as u128
}

fn hash_bytes(h: &mut u64, bytes: &[u8]) {
    for &v in bytes {
        *h = (*h ^ u64::from(v)).wrapping_mul(0x100000001b3)
    }
}
fn actor(kind: &str, n: usize, scale: f64) -> Actor {
    let data = if kind == "triangles" || kind == "degenerate" {
        let mut points = Vec::with_capacity(n * 3);
        let mut indices = Vec::with_capacity(n);
        for i in 0..n {
            let x = i as f64 * 3.0;
            let k = (i * 3) as u32;
            points.extend(
                [
                    [x, 0.0, 0.0],
                    [x + 2.0, 0.0, 0.0],
                    [x, if kind == "degenerate" { 0.0 } else { 1.0 }, 0.0],
                ]
                .map(|p| p.map(|v| v * scale)),
            );
            indices.push([k, k + 1, k + 2]);
        }
        DataSet::surface("triangles", points, &indices)
    } else {
        let mut d = DataSet::structured_grid(
            "surface",
            [n; 3],
            [-scale; 3],
            [2.0 * scale / (n - 1) as f64; 3],
        )
        .unwrap();
        if kind == "general" {
            let nodes = std::sync::Arc::make_mut(&mut d.cells.connectivity);
            let last = nodes.len() - 8;
            nodes[last..last + 4].rotate_left(1);
            nodes[last + 4..].rotate_left(1);
        }
        if kind == "cell_split" {
            let values = (0..d.cells.types.len())
                .map(|i| (i % 2) as f64)
                .collect::<Vec<_>>();
            d = d.with_field(Field::scalar("p", values).on_cells());
        }
        d
    };
    if kind == "cell_split" {
        Actor::new(data).coloured_by_cell("p", gpui_scene3d::TransferFunction::viridis([0.0, 1.0]))
    } else {
        Actor::new(data)
    }
}
fn checks(chunks: &[GpuChunk]) -> (u64, u64, u64, usize, usize, usize) {
    let (mut geometry, mut normal) = (0xcbf29ce484222325, 0xcbf29ce484222325);
    let (mut bytes, mut invalid, mut zero, mut nonunit) = (0, 0, 0, 0);
    for c in chunks {
        bytes += c.byte_len();
        for p in c.origin {
            hash_bytes(&mut geometry, &p.to_bits().to_le_bytes());
        }
        for v in c.positions.iter().chain(&c.scalars) {
            hash_bytes(&mut geometry, &v.to_bits().to_le_bytes());
        }
        for v in c.indices.iter().chain(&c.edges) {
            hash_bytes(&mut geometry, &v.to_le_bytes());
        }
        for v in &c.normals {
            hash_bytes(&mut normal, &v.to_bits().to_le_bytes());
        }
        for n in c.normals.as_chunks::<3>().0 {
            if n.iter().any(|v| !v.is_finite()) {
                invalid += 1;
            }
            if *n == [0.0; 3] { zero += 1; }
            let squared = n.iter().map(|v| f64::from(*v).powi(2)).sum::<f64>();
            if !squared.is_finite() || (squared - 1.0).abs() > 1e-5 { nonunit += 1; }
        }
    }
    (geometry, normal, bytes, invalid, zero, nonunit)
}
fn run(kind: &str, n: usize, scale: f64) {
    let actor = actor(kind, n, scale);
    let expected = checks(&prepare_chunks(&actor, 1_000_000).unwrap());
    let (mut cpus, mut walls, mut calls, mut bytes) =
        (Vec::new(), Vec::new(), Vec::new(), Vec::new());
    for _ in 0..5 {
        let mut probe = AllocProbe::new();
        let cpu = cpu_ns();
        let wall = Instant::now();
        let output = black_box(prepare_chunks(&actor, 1_000_000).unwrap());
        let elapsed = wall.elapsed().as_nanos();
        let cpu = cpu_ns() - cpu;
        let a = probe.sample("surface-normal-preparation");
        cpus.push(cpu);
        walls.push(elapsed);
        calls.push(a.count);
        bytes.push(a.bytes);
        assert_eq!(checks(&output), expected);
    }
    println!(
        r#"{{"kind":"{kind}","n":{n},"scale":{scale},"cpu_ns":{cpus:?},"wall_ns":{walls:?},"allocation_calls":{calls:?},"allocated_bytes":{bytes:?},"geometry_hash":"{:016x}","normal_hash":"{:016x}","payload_bytes":{},"invalid_normals":{},"zero_normals":{},"nonunit_normals":{},"allocator":{}}}"#,
        expected.0,
        expected.1,
        expected.2,
        expected.3,
        expected.4,
        expected.5,
        cfg!(feature = "allocations")
    );
}
fn main() {
    let args: Vec<_> = std::env::args().collect();
    if args.get(1).is_some_and(|a| a == "--rss") {
        let scale = args[2].parse().unwrap();
        let a = actor("triangles", 65536, scale);
        let c = prepare_chunks(&a, 1_000_000).unwrap();
        println!("{:?}", checks(&c));
        return;
    }
    for kind in ["canonical", "cell_split"] {
        for n in [16, 48] {
            for scale in [1.0, 1e-12, 1e12, 1e-30, 1e30] {
                run(kind, n, scale)
            }
        }
    }
    for n in [16, 48] {
        run("general", n, 1.0)
    }
    for kind in ["triangles", "degenerate"] {
        for n in [256, 65536] {
            run(kind, n, 1.0)
        }
    }
}

